insert into messages (id, conversation_id, sender, sender_id, body, created_at) values
  ('a0000007-0000-4000-8000-000000000001', 'a0000006-0000-4000-8000-000000000001', 'zoeker', 'a0000003-0000-4000-8000-00000000000b', 'Goedemiddag, is Hereweg 112 nog beschikbaar? En klopt het dat de tuin op het zuidwesten ligt?', now() - interval '7200 minutes'),
  ('a0000007-0000-4000-8000-000000000002', 'a0000006-0000-4000-8000-000000000001', 'makelaar', 'a0000003-0000-4000-8000-000000000001', 'Goedemiddag Anna, ja de woning is nog beschikbaar. De achtertuin ligt op het zuidwesten, dus tot laat in de avond zon.', now() - interval '7110 minutes'),
  ('a0000007-0000-4000-8000-000000000003', 'a0000006-0000-4000-8000-000000000001', 'zoeker', 'a0000003-0000-4000-8000-00000000000b', 'Mooi! Is er al een bezichtiging mogelijk deze week?', now() - interval '5760 minutes'),
  ('a0000007-0000-4000-8000-000000000004', 'a0000006-0000-4000-8000-000000000001', 'makelaar', 'a0000003-0000-4000-8000-000000000001', 'Zeker, je kunt zelf een moment kiezen op de woningpagina onder "Bezichtiging plannen".', now() - interval '5720 minutes'),
  ('a0000007-0000-4000-8000-000000000005', 'a0000006-0000-4000-8000-000000000001', 'zoeker', 'a0000003-0000-4000-8000-00000000000b', 'Gedaan, morgen om 10:00. Hartelijk dank!', now() - interval '4320 minutes'),
  ('a0000007-0000-4000-8000-000000000006', 'a0000006-0000-4000-8000-000000000001', 'makelaar', 'a0000003-0000-4000-8000-000000000001', 'Top, tot morgen! Neem gerust uw partner mee.', now() - interval '120 minutes'),
  ('a0000007-0000-4000-8000-000000000007', 'a0000006-0000-4000-8000-000000000002', 'zoeker', 'a0000003-0000-4000-8000-00000000000c', 'Hallo, zijn er servicekosten voor het appartement en hoe hoog zijn die?', now() - interval '1560 minutes'),
  ('a0000007-0000-4000-8000-000000000008', 'a0000006-0000-4000-8000-000000000002', 'makelaar', 'a0000003-0000-4000-8000-000000000002', 'Dag Piet, de servicekosten zijn € 148 per maand. De VvE-stukken stuur ik graag toe.', now() - interval '1200 minutes'),
  ('a0000007-0000-4000-8000-000000000009', 'a0000006-0000-4000-8000-000000000002', 'zoeker', 'a0000003-0000-4000-8000-00000000000c', 'Graag! En is er een parkeerplek bij het appartement?', now() - interval '45 minutes'),
  ('a0000007-0000-4000-8000-00000000000a', 'a0000006-0000-4000-8000-000000000003', 'zoeker', 'a0000003-0000-4000-8000-00000000000d', 'Is het mogelijk om de woning ook een tweede keer te bekijken?', now() - interval '11520 minutes'),
  ('a0000007-0000-4000-8000-00000000000b', 'a0000006-0000-4000-8000-000000000003', 'makelaar', 'a0000003-0000-4000-8000-000000000003', 'Ja hoor, plan gerust een nieuw moment in.', now() - interval '11490 minutes'),
  ('a0000007-0000-4000-8000-00000000000c', 'a0000006-0000-4000-8000-000000000003', 'zoeker', 'a0000003-0000-4000-8000-00000000000d', 'Dank u wel, gedaan.', now() - interval '11400 minutes');
-- Gelezen: gesprek 1 heeft een ongelezen antwoord van de makelaar, gesprek 2 een ongelezen vraag van de zoeker, gesprek 3 is gelezen.
update messages set read_at = created_at + interval '5 minutes' where conversation_id in ('a0000006-0000-4000-8000-000000000003');
update messages set read_at = created_at + interval '5 minutes' where conversation_id = 'a0000006-0000-4000-8000-000000000001' and created_at < now() - interval '1 day';
update messages set read_at = created_at + interval '5 minutes' where conversation_id = 'a0000006-0000-4000-8000-000000000002' and sender = 'makelaar';
update conversations c set last_message_at = (select max(created_at) from messages m where m.conversation_id = c.id) where c.id in ('a0000006-0000-4000-8000-000000000001', 'a0000006-0000-4000-8000-000000000002', 'a0000006-0000-4000-8000-000000000003');

